from __future__ import annotations

import os
import re
import shutil
import subprocess
from collections.abc import Mapping
from pathlib import Path

APP_NAME = "cm"
MIN_BASH_VERSION = (4, 4)
COMPLETION_FILENAME = APP_NAME

_PROVIDER_CHOICES = "auto bedrock deepseek"
_COMMANDS = "generate"
_OPTIONS = "-h --help -s --staged --provider --model --config --completions --version"

_BASH_COMPLETION = f"""\
# bash completion for {APP_NAME}
# Generated by `{APP_NAME} --completions`. Static output; do not edit by hand.
_{APP_NAME}_completion() {{
    local cur prev i seen_command
    COMPREPLY=()
    cur="${{COMP_WORDS[COMP_CWORD]}}"
    prev="${{COMP_WORDS[COMP_CWORD-1]}}"
    seen_command=""

    for ((i = 1; i < COMP_CWORD; i++)); do
        if [[ " {_COMMANDS} " == *" ${{COMP_WORDS[i]}} "* ]]; then
            seen_command=1
        fi
    done

    case "$prev" in
        --provider)
            COMPREPLY=( $(compgen -W "{_PROVIDER_CHOICES}" -- "$cur") )
            return 0
            ;;
        --model|--config|--completions)
            return 0
            ;;
    esac

    if [[ "$cur" == -* ]]; then
        COMPREPLY=( $(compgen -W "{_OPTIONS}" -- "$cur") )
        compopt -o nosort 2>/dev/null || true
    elif [[ -z "$seen_command" ]]; then
        COMPREPLY=( $(compgen -W "{_COMMANDS}" -- "$cur") )
        compopt -o nosort 2>/dev/null || true
    fi

    return 0
}}

complete -o nosort -F _{APP_NAME}_completion {APP_NAME}
"""

_BASH_VERSION = re.compile(r"version (\d+)\.(\d+)")


def generate_bash_completion() -> str:
    """Return the static bash completion script.

    The script is generated from the option and provider lists above rather
    than relying on click's dynamic completion at shell startup.
    """
    return _BASH_COMPLETION


def completion_dir(environ: Mapping[str, str] | None = None) -> Path:
    """Return the bash-completion directory, honouring $XDG_DATA_HOME."""
    env = os.environ if environ is None else environ
    data_home = env.get("XDG_DATA_HOME")
    base = Path(data_home).expanduser() if data_home else Path.home() / ".local/share"
    return base / "bash-completion" / "completions"


def completion_path(environ: Mapping[str, str] | None = None) -> Path:
    """Return the path where the completion script is written."""
    return completion_dir(environ) / COMPLETION_FILENAME


def install_completion(environ: Mapping[str, str] | None = None) -> Path:
    """Write the completion script and return its path."""
    path = completion_path(environ)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(generate_bash_completion(), encoding="utf-8")
    return path


def installed_bash_version() -> tuple[int, int] | None:
    """Return the (major, minor) version of the bash on PATH, if available."""
    bash = shutil.which("bash")
    if bash is None:
        return None

    try:
        result = subprocess.run(
            [bash, "--version"],
            capture_output=True,
            text=True,
            timeout=5,
        )
    except (OSError, subprocess.TimeoutExpired):
        return None

    match = _BASH_VERSION.search(result.stdout)
    if match is None:
        return None
    return int(match.group(1)), int(match.group(2))
